import { useState } from "react";
import FlightControls from "./FlightControls";
import MapView from "./MapView";

function App() {
  const [path, setPath] = useState([]);

  const fetchData = async (startTime, duration) => {
    try {
      const res = await fetch(
        `http://localhost:3000/api/flight-window?start=${startTime}&duration=${duration}`
      );

      const result = await res.json();
      setPath(result.path || []);
    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div>
      <h2 style={{ textAlign: "center" }}>🚁 Drone Flight Replay</h2>

      <FlightControls onFetch={fetchData} />

      <MapView path={path} />
    </div>
  );
}

export default App;
